code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        long total = 0;
        for (long i = 1; i <= n; i++) {
            total += i * i;
        }
        System.out.println(total);
    }
}
